  template <typename T>
  class ComPtr {
  public:
    ComPtr() = default;

    ComPtr(const ComPtr&) = delete;
    ComPtr& operator=(const ComPtr&) = delete;

    ComPtr(ComPtr&& other) noexcept
    : m_ptr(other.m_ptr) {
      other.m_ptr = nullptr;
    }

    ComPtr& operator=(ComPtr&& other) noexcept {
      if (this != &other) {
        reset();
        m_ptr = other.m_ptr;
        other.m_ptr = nullptr;
      }
      return *this;
    }

    ~ComPtr() {
      reset();
    }

    T* Get() const {
      return m_ptr;
    }

    T** GetAddressOf() {
      return &m_ptr;
    }

    T** ReleaseAndGetAddressOf() {
      reset();
      return &m_ptr;
    }

    void Reset() {
      reset();
    }

    template <typename U>
    HRESULT As(ComPtr<U>* other) const {
      if (!other)
        return E_POINTER;
      if (!m_ptr) {
        other->Reset();
        return E_NOINTERFACE;
      }

      return m_ptr->QueryInterface(__uuidof(U), reinterpret_cast<void**>(other->ReleaseAndGetAddressOf()));
    }

    T* operator->() const {
      return m_ptr;
    }

    explicit operator bool() const {
      return m_ptr != nullptr;
    }

  private:
    void reset() {
      if (m_ptr) {
        m_ptr->Release();
        m_ptr = nullptr;
      }
    }

    T* m_ptr = nullptr;
  };

