  class ShaderCompiler {
  public:
    ShaderCompiler() {
      static const char* kCompilerDlls[] = {
        "d3dcompiler_47.dll",
        "d3dcompiler_43.dll",
      };

      for (const char* dllName : kCompilerDlls) {
        m_module = LoadLibraryA(dllName);
        if (!m_module)
          continue;

        m_compile = reinterpret_cast<D3DCompileFn>(GetProcAddress(m_module, "D3DCompile"));
        if (m_compile)
          return;

        FreeLibrary(m_module);
        m_module = nullptr;
      }
    }

    ~ShaderCompiler() {
      if (m_module)
        FreeLibrary(m_module);
    }

    bool available() const {
      return m_compile != nullptr;
    }

    bool compile(
        const char* source,
        const char* entry,
        const char* target,
        ComPtr<ID3DBlob>& blob,
        std::string& error) const {
      if (!m_compile) {
        error = "D3DCompile is unavailable. Install a D3D compiler runtime such as d3dcompiler_47.dll.";
        return false;
      }

      UINT flags = D3DCOMPILE_ENABLE_STRICTNESS;
#ifndef NDEBUG
      flags |= D3DCOMPILE_DEBUG | D3DCOMPILE_SKIP_OPTIMIZATION;
#else
      flags |= D3DCOMPILE_OPTIMIZATION_LEVEL3;
#endif

      ComPtr<ID3DBlob> errors;
      HRESULT hr = m_compile(
        source,
        std::strlen(source),
        nullptr,
        nullptr,
        nullptr,
        entry,
        target,
        flags,
        0,
        blob.ReleaseAndGetAddressOf(),
        errors.ReleaseAndGetAddressOf());

      if (FAILED(hr)) {
        error = formatHResult(hr);
        if (errors && errors->GetBufferPointer() && errors->GetBufferSize()) {
          error += " | ";
          error.append(
            static_cast<const char*>(errors->GetBufferPointer()),
            static_cast<const char*>(errors->GetBufferPointer()) + errors->GetBufferSize());
        }
        return false;
      }

      return true;
    }

  private:
    using D3DCompileFn = HRESULT (WINAPI*)(
      LPCVOID,
      SIZE_T,
      LPCSTR,
      const D3D_SHADER_MACRO*,
      ID3DInclude*,
      LPCSTR,
      LPCSTR,
      UINT,
      UINT,
      ID3DBlob**,
      ID3DBlob**);

    HMODULE m_module = nullptr;
    D3DCompileFn m_compile = nullptr;
  };

  // A stand-in for Unreal Engine 4's TAAU compute pass (see
  // testUpscalerReplace): scene color t1, depth t2, velocity t3, output u0,
  // the view size and jitter in cb0[27] and cb0[28], ClipToPrevClip in
  // cb1[122..125]. It writes magenta.
  const char* const kUpscalerTaaCs = R"(
Texture2D<float4> color : register(t1);
Texture2D<float> depth : register(t2);
Texture2D<float4> velocity : register(t3);
RWTexture2D<float4> output : register(u0);
cbuffer Params : register(b0) { float4 params[29]; };
cbuffer View : register(b1) { float4 view[126]; };
[numthreads(8, 8, 1)]
void main(uint2 id : SV_DispatchThreadID) {
  float4 unused = color.Load(int3(0, 0, 0)) + depth.Load(int3(0, 0, 0)) + velocity.Load(int3(0, 0, 0))
    + params[27] + params[28] + view[122];
  output[id] = float4(1.0f, 0.0f, 1.0f, 1.0f) + min(abs(unused), 0.0f);
}
)";

  // The FNV-1a hash DXUP names shaders by.
  uint64_t dxupBytecodeHash(const void* data, size_t size) {
    uint64_t hash = 1469598103934665603ull;
    for (size_t i = 0; i < size; i++) {
      hash ^= static_cast<const uint8_t*>(data)[i];
      hash *= 1099511628211ull;
    }
    return hash;
  }

